   V("would like", "/wʊd ˈlaɪk/", "хотів би", "хотел бы", "I'd like to go."),
   V("decide", "/dɪˈsaɪd/", "вирішувати", "решать", "We decided to stay."),
   V("hope", "/həʊp/", "сподіватися", "надеяться", "I hope to see you."),
   V("try", "/traɪ/", "намагатися", "стараться", "Try to relax."),
   V("learn", "/lɜːn/", "вчитися", "учиться", "I'm learning to drive."),
